import { ActivityItem } from '@refy-design/web';
import { Button } from '@refy-design/web';
import type { ComponentProps } from 'react';
import { useState } from 'react';
export function Example() {
  const args: Pick<
    ComponentProps<typeof ActivityItem>,
    'actor' | 'title' | 'timestamp' | 'description' | 'badge' | 'metadata'
  > = {
    actor: { name: 'Ana Silva', initials: 'AS' },
    title: 'commented on the content review',
    timestamp: 'Oct 23, 14:30',
    description: 'The navigation is clearer. We can go ahead with this proposal.',
    badge: { label: 'Comment', tone: 'info' },
    metadata: 'Aurora project · References',
  };
  const [read, setRead] = useState(false);
  return (
    <ActivityItem
      {...args}
      action={
        <Button size="sm" variant="ghost" disabled={read} onClick={() => setRead(true)}>
          {read ? 'Read' : 'Mark as read'}
        </Button>
      }
    />
  );
}

